@SpringBootTest
@AutoConfigureMockMvc
class OrderApiIT {
  @Autowired MockMvc mvc;

  @Test
  void list_orders_returns_200() throws Exception {
    mvc.perform(get("/api/orders")) // no auth header
       .andExpect(status().isOk());
  }
